$ErrorActionPreference='Stop'
Set-Location -LiteralPath (Split-Path -Parent $PSScriptRoot)
$baseline=@((Get-Content TestResults/courts-flank-v0230-baseline.json -Raw|ConvertFrom-Json).models)+@((Get-Content TestResults/courts-flank-v0230-baseline-remainder.json -Raw|ConvertFrom-Json).models)
$selected=@((Get-Content TestResults/courts-pulse-v0230-original-w10-pilot.json -Raw|ConvertFrom-Json).models)+@((Get-Content TestResults/courts-pulse-v0230-original-w10-remainder.json -Raw|ConvertFrom-Json).models)
if($baseline.Count -ne 9 -or $selected.Count -ne 9){throw 'Expected nine selected pairs'}
$pairs=@(foreach($r in $selected){
    $b=@($baseline|Where-Object {$_.Seed -eq $r.Seed -and $_.Policy -eq $r.Policy})[0]
    foreach($a in @($b,$r)){if($a.State -ne 'Won' -or $a.Kills -ne 780 -or -not $a.AllSpawned -or $a.Remaining -ne 0 -or $a.Core -ne 300 -or $a.Towers -ne 14 -or $a.Sites -ne 24 -or $a.StartingCredits -ne 280){throw 'Selected full-investment scope differs'}}
    if($b.Spent -ne $r.Spent -or ($b.Cards -join '/') -ne ($r.Cards -join '/')){throw 'Pair spend/cards differ; preserve and review separately'}
    $aOrder=@($b.PurchaseLog|ForEach-Object {$_ -replace '^\d+\.\d+ ',''});$bOrder=@($r.PurchaseLog|ForEach-Object {$_ -replace '^\d+\.\d+ ',''})
    [ordered]@{seed=$r.Seed;policy=$r.Policy;baseline=$b;candidate=$r;sameActualPurchaseOrder=@(Compare-Object $aOrder $bOrder -SyncWindow 0).Count -eq 0;actualPurchaseTimesIdentical=($b.PurchaseLog -join '|') -eq ($r.PurchaseLog -join '|')}
})
$openingBaseline=(Get-Content TestResults/courts-opening-v0230-baseline.json -Raw|ConvertFrom-Json).models
$opening=(Get-Content TestResults/courts-opening-v0230-w10.json -Raw|ConvertFrom-Json).models
foreach($a in @($openingBaseline)+@($opening)){if($a.Spent -ne 280 -or $a.Towers -ne 7 -or $a.State -ne 'Won' -or $a.Kills -ne 780){throw 'Opening budget/outcome differs'}}
$geometry=Get-Content TestResults/courts-pulse-v0230-original-w10-geometry.json -Raw|ConvertFrom-Json
if($geometry.onlyChangedCellStarts -ne 128 -or -not $geometry.speciesCountIntervalSwarmAndFirstEntranceExact){throw 'Pack timing scope differs'}
